{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table `prolicious-wh.maplemonk.prolicious_sale_channel_drr_view` as with date_range as ( select min(order_date) as min_date, max(order_date) as max_date from `prolicious-wh.maplemonk.prolicious_wh_sales_consolidated` where shop_name <> \'B2B\' ), date_spine as ( select date_array from date_range, unnest(generate_date_array(min_date, max_date, interval 1 day)) as date_array ), marketplaces as ( select distinct case when upper(shop_name) like \'%FLIPKART%\' then \'FLIPKART\' else upper(shop_name) end as marketplace, upper(product_sub_category) as product_sub_category from `prolicious-wh.maplemonk.prolicious_wh_sales_consolidated` where shop_name <> \'B2B\' ), dense_grid as ( select d.date_array as order_date, m.marketplace, m.product_sub_category from date_spine d cross join marketplaces m ), daily_agg as ( select order_date, case when upper(shop_name) like \'%FLIPKART%\' then \'FLIPKART\' else upper(shop_name) end as marketplace, upper(product_sub_category) as product_sub_category, sum(ifnull(selling_price,0)) as daily_sales from `prolicious-wh.maplemonk.prolicious_wh_sales_consolidated` where shop_name <> \'B2B\' group by 1,2,3 ), dense_data as ( select g.order_date, g.marketplace, g.product_sub_category, coalesce(a.daily_sales, 0) as daily_sales from dense_grid g left join daily_agg a on g.order_date = a.order_date and g.marketplace = a.marketplace and g.product_sub_category = a.product_sub_category ), monthly_sales as ( select date_trunc(order_date, month) as month_start, marketplace, product_sub_category, sum(daily_sales) as month_total from dense_data group by 1, 2, 3 ), monthly_with_lag as ( select month_start, marketplace, product_sub_category, lag(month_total) over (partition by marketplace, product_sub_category order by month_start) as lm_actual, lag(extract(day from last_day(month_start))) over (partition by marketplace, product_sub_category order by month_start) as days_in_last_month from monthly_sales ), rolling_base as ( select d.order_date, d.marketplace, d.product_sub_category, d.daily_sales, sum(d.daily_sales) over (partition by d.marketplace, d.product_sub_category, date_trunc(d.order_date, month) order by d.order_date) as tm_actual, m.lm_actual as lm_actual, sum(d.daily_sales) over (partition by d.marketplace, d.product_sub_category order by d.order_date rows between 89 preceding and current row) as l3m_actual, sum(d.daily_sales) over (partition by d.marketplace, d.product_sub_category order by d.order_date rows between 179 preceding and current row) as l6m_actual, sum(d.daily_sales) over (partition by d.marketplace, d.product_sub_category order by d.order_date rows between 269 preceding and current row) as l9m_actual, sum(d.daily_sales) over (partition by d.marketplace, d.product_sub_category order by d.order_date rows between 364 preceding and current row) as l12m_actual, extract(day from d.order_date) as days_passed, extract(day from last_day(d.order_date)) as days_in_month, m.days_in_last_month from dense_data d left join monthly_with_lag m on date_trunc(d.order_date, month) = m.month_start and d.marketplace = m.marketplace and d.product_sub_category = m.product_sub_category ) select order_date as Date, marketplace as Marketplace, product_sub_category, tm_actual as tm_actual, lm_actual as lm_actual, tm_actual / nullif(days_passed, 0) as tm_rr, lm_actual / nullif(days_in_last_month, 0) as lm_rr, l3m_actual / 90.0 as l3m_rr, l6m_actual / 180.0 as l6m_rr, l9m_actual / 270.0 as l9m_rr, l12m_actual / 365.0 as l12m_rr, (tm_actual / nullif(days_passed, 0)) * days_in_month as tm_likely from rolling_base;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            